What will be the output of this code when the input is 3?

```csharp
using System;

namespace MyApplication
{
    class Program
    {
        static void Main(string[] args)
        {
            int binary = Convert.ToInt32(Console.ReadLine());
            switch (binary)
            {
                case 0:
                    Console.Write("Zero");
                    break;
                case 1:
                    Console.Write("One");
                    break;
                default:
                    Console.WriteLine("Not valid");
                    break;
            }
        }
    }
}
```

